-- Refine existing movement taxonomy; preserve every historical snapshot.
begin;
alter table public.workout_movements add column suggested_intent text check(length(suggested_intent) between 1 and 80);
grant insert(suggested_intent) on public.workout_movements to authenticated;
-- Edition 1 catalog refinements. Future catalog edits require a forward migration.
create function public.movement_intent(p_key text) returns jsonb
language sql immutable security invoker set search_path='' as $fn$
 select value from jsonb_array_elements($registry$[{"key":"flat_press","title":"Flat Chest Press","pattern":"horizontal_push","muscle":"pectorals","exerciseType":"compound","exercises":["barbell_bench_press","paused_barbell_bench_press","dumbbell_bench_press","neutral_grip_dumbbell_bench_press","single_arm_dumbbell_bench_press","seated_machine_chest_press","plate_loaded_chest_press","push_up","knee_push_up","smith_machine_bench_press"],"patternId":"e33054bc-391e-503b-97c3-031ce9cbdb52","muscleId":"55a2b8fb-751c-5e83-b8bf-54ded38b8ac2"},{"key":"close_grip_press","title":"Close-Grip Press","pattern":"horizontal_push","muscle":"pectorals","exerciseType":"compound","exercises":["close_grip_barbell_bench_press","close_grip_push_up"],"patternId":"e33054bc-391e-503b-97c3-031ce9cbdb52","muscleId":"55a2b8fb-751c-5e83-b8bf-54ded38b8ac2"},{"key":"floor_press","title":"Floor Press","pattern":"horizontal_push","muscle":"pectorals","exerciseType":"compound","exercises":["dumbbell_floor_press"],"patternId":"e33054bc-391e-503b-97c3-031ce9cbdb52","muscleId":"55a2b8fb-751c-5e83-b8bf-54ded38b8ac2"},{"key":"dip","title":"Dip","pattern":"horizontal_push","muscle":"pectorals","exerciseType":"compound","exercises":["parallel_bar_dip","assisted_dip_machine"],"patternId":"e33054bc-391e-503b-97c3-031ce9cbdb52","muscleId":"55a2b8fb-751c-5e83-b8bf-54ded38b8ac2"},{"key":"incline_push_up","title":"Incline Push-Up","pattern":"horizontal_push","muscle":"pectorals","exerciseType":"compound","exercises":["incline_push_up"],"patternId":"e33054bc-391e-503b-97c3-031ce9cbdb52","muscleId":"55a2b8fb-751c-5e83-b8bf-54ded38b8ac2"},{"key":"incline_press","title":"Incline Chest Press","pattern":"incline_push","muscle":"pectorals","exerciseType":"compound","exercises":[],"patternId":"3b4daf6a-9e6b-5a6b-a225-208a18c94c2a","muscleId":"55a2b8fb-751c-5e83-b8bf-54ded38b8ac2"},{"key":"chest_fly","title":"Chest Fly","pattern":"horizontal_adduction","muscle":"pectorals","exerciseType":"isolation","exercises":["dumbbel