w_flexion","muscle":"biceps","exerciseType":"isolation","exercises":["dumbbell_hammer_curl","cross_body_hammer_curl","rope_hammer_curl"],"patternId":"a60b2134-cf9c-5766-95e4-4592856168bd","muscleId":"f77b2bde-68f0-5811-ae62-79c68313161e"},{"key":"lengthened_curl","title":"Behind-Body Curl","pattern":"elbow_flexion","muscle":"biceps","exerciseType":"isolation","exercises":["incline_dumbbell_curl","single_arm_behind_body_cable_curl"],"patternId":"a60b2134-cf9c-5766-95e4-4592856168bd","muscleId":"f77b2bde-68f0-5811-ae62-79c68313161e"},{"key":"supported_curl","title":"Supported / High-Arm Curl","pattern":"elbow_flexion","muscle":"biceps","exerciseType":"isolation","exercises":["dumbbell_concentration_curl","spider_dumbbell_curl","high_cable_curl"],"patternId":"a60b2134-cf9c-5766-95e4-4592856168bd","muscleId":"f77b2bde-68f0-5811-ae62-79c68313161e"},{"key":"pushdown","title":"Triceps Pushdown","pattern":"elbow_extension","muscle":"triceps","exerciseType":"isolation","exercises":["rope_triceps_pushdown","straight_bar_triceps_pushdown","single_arm_cable_pushdown"],"patternId":"9845acb8-7945-518b-90f7-f859e1535dcb","muscleId":"a25576a2-9233-5e0c-b180-c43b2f1b3ce4"},{"key":"overhead_extension","title":"Overhead Triceps Extension","pattern":"elbow_extension","muscle":"triceps","exerciseType":"isolation","exercises":["standing_overhead_dumbbell_triceps_extension","overhead_cable_triceps_extension"],"patternId":"9845acb8-7945-518b-90f7-f859e1535dcb","muscleId":"a25576a2-9233-5e0c-b180-c43b2f1b3ce4"},{"key":"lying_extension","title":"Lying Triceps Extension","pattern":"elbow_extension","muscle":"triceps","exerciseType":"isolation","exercises":["lying_dumbbell_triceps_extension","lying_ez_bar_triceps_extension"],"patternId":"9845acb8-7945-518b-90f7-f859e1535dcb","muscleId":"a25576a2-9233-5e0c-b180-c43b2f1b3ce4"},{"key":"kickback","title":"Triceps Kickback / Cross-Body Extension","pattern":"elbow_extension","muscle":"triceps","exerciseType":"isolation","exercises":["dumbbell_triceps_kickback","cross_body_cable_triceps_extension"],"patternId":"9845acb8-7945-518b-90f7-f859e1535dcb","muscleId":"a25576a2-9233-5e0c-b180-c43b2f1b3ce4"},{"key":"crunch","title":"Trunk Curl","pattern":"spinal_flexion","muscle":"abdominals","exerciseType":"isolation","exercises":["floor_crunch","kneeling_cable_crunch"],"patternId":"c1391397-e7dd-577d-a70e-3042d1816402","muscleId":"b48b4f27-955a-5147-b3b6-3a92667f8d00"},{"key":"reverse_crunch","title":"Reverse Crunch","pattern":"spinal_flexion","muscle":"abdominals","exerciseType":"isolation","exercises":["reverse_crunch"],"patternId":"c1391397-e7dd-577d-a70e-3042d1816402","muscleId":"b48b4f27-955a-5147-b3b6-3a92667f8d00"},{"key":"bicycle","title":"Bicycle Crunch","pattern":"rotation","muscle":"obliques","exerciseType":"compound","exercises":["bicycle_crunch"],"patternId":"5368df2b-bce2-5fee-bb2e-726ea58e7eac","muscleId":"2fe7b6cb-1d74-514c-8a4f-0e7957762a83"},{"key":"wood_chop","title":"Diagonal Wood Chop","pattern":"rotation","muscle":"obliques","exerciseType":"compound","exercises":["high_to_low_cable_wood_chop","low_to_high_cable_wood_chop"],"patternId":"5368df2b-bce2-5fee-bb2e-726ea58e7eac","muscleId":"2fe7b6cb-1d74-514c-8a4f-0e7957762a83"},{"key":"reverse_curl","title":"Reverse-Grip Curl","pattern":"elbow_flexion","muscle":"biceps","exerciseType":"isolation","exercises":["reverse_grip_ez_bar_curl"],"patternId":"a60b2134-cf9c-5766-95e4-4592856168bd","muscleId":"f77b2bde-68f0-5811-ae62-79c68313161e"},{"key":"rear_delt_pull","title":"Rear-Delt Face Pull","pattern":"horizontal_pull","muscle":"posterior_deltoids","exerciseType":"compound","exercises":["cable_face_pull"],"patternId":"ca7204d7-f2ef-591e-bd6b-bd9370dea436","muscleId":"b0620f84-d8ba-516b-a6cc-4bdf5d87c284"}]$registry$::jsonb) where value->>'key'=p_key
$fn$;
revoke all on function public.movement_intent(text) from public,anon,service_role;
grant execute on function public.movement_intent(text) to authenticated;
create or replace function body_private.ad_hoc_session_input() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if tg_op='UPDATE' then
  if row(new.ad_hoc_focus,new.ad_hoc_start_nonce) is distinct from row(old.ad_hoc_focus,old.ad_hoc_start_nonce) then raise exception 'Workout focus is immutable' using errcode='23514';end if;return new;
 end if;
 if (new.ad_hoc_focus is null)<>(new.ad_hoc_start_nonce is null) then raise exception 'Focus and retry identity are paired' using errcode='22023';end if;
 if new.ad_hoc_focus is not null then
  if new.source_program_version_id is not null or new.ad_hoc_start_nonce is null or jsonb_typeof(new.ad_hoc_focus)<>'array' or jsonb_array_length(new.ad_hoc_focus) not between 1 and 6 then raise exception 'Invalid suggested workout' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(new.ad_hoc_focus) x
    group by coalesce(x->>'intent',(x->>'pattern')||':'||(x->>'muscle')||':'||(x->>'exerciseType')) having count(*)>1)
    or exists(select 1 from jsonb_array_elements(new.ad_hoc_focus) x group by x->>'pattern',x->>'muscle' having count(*)>1 and bool_or(x->>'intent' is null))
    then raise exception 'Choose distinct movement intents' using errcode='22023';end if;
 end if;
 return new;
end $$;

create or replace function body_private.program_movement_snapshot() returns trigger language plpgsql security invoker set search_path='' as $$
declare w public.workout_sessions;v public.program_versions;day jsonb;slot jsonb;pattern_name text;intent jsonb;
begin
 select * into w from public.workout_sessions where id=new.workout_session_id and owner_id=auth.uid() for update nowait;
 if w.id is null then raise exception 'Workout unavailable' using errcode='42501';end if;
 if w.status<>'in_progress' or w.last_activity_at is not null and clock_timestamp()-w.last_activity_at>=make_interval(hours=>(public.workout_policy()->>'expire_hours')::int) then raise exception 'Workout closed or expired' using errcode='23514';end if;
 if w.source_program_version_id is null then
  if new.position not between 1 and 100 or new.movement_nonce is null or new.suggested_pattern_id is null or new.suggested_muscle_id is null or new.suggested_type is null then raise exception 'Choose a supported movement' using errcode='22023';end if;
  if not exists(select 1 from public.exercises e join public.exercise_movement_patterns ep on ep.exercise_id=e.id and ep.is_primary join public.exercise_muscles em on em.exercise_id=e.id and em.muscle_role='primary' where e.archived_at is null and e.exercise_type=new.suggested_type and ep.movement_pattern_id=new.suggested_pattern_id and em.muscle_group_id=new.suggested_muscle_id and public.exercise_logging_kind(e.id) in('loaded','bodyweight')) then raise exception 'No supported exercises for this movement' using errcode='22023';end if;
  if new.suggested_intent is not null then
   intent:=public.movement_intent(new.suggested_intent);
   if intent is null or (intent->>'patternId')::uuid<>new.suggested_pattern_id or (intent->>'muscleId')::uuid<>new.suggested_muscle_id or intent->>'exerciseType'<>new.suggested_type then raise exception 'Unsupported movement intent' using errcode='22023';end if;
   if jsonb_array_length(intent->'exercises')>0 and not exists(select 1 from public.exercises e where e.owner_id is null and e.archived_at is null and e.slug in(select jsonb_array_elements_text(intent->'exercises')) and public.exercise_logging_kind(e.id) in('loaded','bodyweight')) then raise exception 'No supported exercises for intent' using errcode='22023';end if;
  end if;
  select name into pattern_name from public.movement_patterns where id=new.suggested_pattern_id;
  new.owner_id:=auth.uid();new.slot_identity:=new.id;
  new.slot_snapshot:=jsonb_build_object('intent',new.suggested_intent,'origin','ad_hoc','id',new.id,'title',coalesce(new.suggested_title,pattern_name),'movement_pattern_id',new.suggested_pattern_id,'primary_muscle_id',new.suggested_muscle_id,'required_exercise_type',new.suggested_type,'target_sets',3,'target_reps_min',case when new.suggested_type='compound' then 8 else 10 end,'target_reps_max',case when new.suggested_type='compound' then 12 else 15 end,'equipment','[]'::jsonb,'sets','[]'::jsonb);
  return new;
 end if;
 if new.suggested_intent is not null or new.suggested_pattern_id is not null or new.suggested_muscle_id is not null or new.suggested_type is not null or new.movement_nonce is not null then raise exception 'Program intent is immutable' using errcode='23514';end if;
 select * into v from public.program_versions where id=w.source_program_version_id and owner_id=auth.uid();
 select value into day from jsonb_array_elements(v.definition->'days') where (value->>'id')::uuid=w.source_program_day_id;
 if new.position is null or new.position not between 1 and 100 then raise exception 'Invalid movement order' using errcode='22023';end if;
 select value into slot from jsonb_array_elements(day->'slots') order by (value->>'position')::int offset new.position-1 limit 1;
 if slot is null then raise exception 'Program movement unavailable' using errcode='23514';end if;
 new.owner_id:=auth.uid();new.slot_identity:=(slot->>'id')::uuid;new.slot_snapshot:=slot;return new;
end $$;

create or replace function body_private.initialize_ad_hoc_movements() returns trigger language plpgsql security invoker set search_path='' as $$
declare slot jsonb;n integer:=0;
begin
 if new.ad_hoc_focus is null then return null;end if;
 for slot in select value from jsonb_array_elements(new.ad_hoc_focus) loop
  n:=n+1;
  insert into public.workout_movements(owner_id,workout_session_id,position,suggested_pattern_id,suggested_muscle_id,suggested_type,suggested_title,movement_nonce,suggested_intent)
  values(auth.uid(),new.id,n,(slot->>'pattern')::uuid,(slot->>'muscle')::uuid,slot->>'exerciseType',slot->>'title',md5(new.id::text||':'||n)::uuid,slot->>'intent');
 end loop;return null;
end $$;

create or replace function public.edit_suggested_movement(p_session uuid,p_request uuid,p_slot jsonb default null,p_remove uuid default null,p_keep boolean default false) returns uuid language plpgsql security invoker set search_path='' as $$
declare w public.workout_sessions;m public.workout_movements;retry public.workout_movements;recorded boolean;result_id uuid;n integer;
begin
 if auth.uid() is null then raise exception 'Sign in required' using errcode='42501';end if;
 select * into w from public.workout_sessions where id=p_session and owner_id=auth.uid() for update;
 if w.id is null then raise exception 'Workout unavailable' using errcode='42501';end if;
 if (public.workout_continuity(w.id)->>'state')='expired' then return null;end if;
 if w.status<>'in_progress' or w.source_program_version_id is not null or p_request is null then raise exception 'Ad-hoc active workout required' using errcode='23514';end if;
 if p_slot is not null then
  select * into retry from public.workout_movements where owner_id=auth.uid() and movement_nonce=p_request;
  if retry.id is not null then
   if retry.workout_session_id<>w.id or retry.suggested_pattern_id is distinct from (p_slot->>'pattern')::uuid or retry.suggested_muscle_id is distinct from (p_slot->>'muscle')::uuid or retry.suggested_type is distinct from p_slot->>'exerciseType' or retry.suggested_title is distinct from p_slot->>'title' or retry.suggested_intent is distinct from p_slot->>'intent' then raise exception 'Movement request reused' using errcode='23514';end if;return retry.id;
  end if;
 end if;
 if p_remove is not null then
  select * into m from public.workout_movements where id=p_remove and owner_id=auth.uid() and workout_session_id=w.id and suggested_pattern_id is not null;
  if m.id is null then raise exception 'Movement unavailable' using errcode='42501';end if;
  select exists(select 1 from public.workout_exercises e join public.workout_sets z on z.workout_exercise_id=e.id and z.owner_id=e.owner_id where e.program_movement_id=m.id and e.owner_id=auth.uid() and e.removed_at is null and z.deleted_at is null and (not z.is_automatic or z.inputs_confirmed or z.status='completed')) into recorded;
  if recorded and (p_slot is null or not p_keep) then raise exception 'Keep recorded movement and add a replacement' using errcode='P0001';end if;
  if not recorded and m.removed_at is null then update public.workout_movements set removed_at=clock_timestamp() where id=m.id and owner_id=auth.uid();end if;
 end if;
 if p_slot is null then if p_remove is null then raise exception 'Choose a movement' using errcode='22023';end if;return m.id;end if;
 select coalesce(max(position),0)+1 into n from public.workout_movements where workout_session_id=w.id and owner_id=auth.uid();
 insert into public.workout_movements(owner_id,workout_session_id,position,suggested_pattern_id,suggested_muscle_id,suggested_type,suggested_title,movement_nonce,suggested_intent)
 values(auth.uid(),w.id,n,(p_slot->>'pattern')::uuid,(p_slot->>'muscle')::uuid,p_slot->>'exerciseType',p_slot->>'title',p_request,p_slot->>'intent') returning id into result_id;return result_id;
end $$;
revoke all on all functions in schema body_private from public,anon,authenticated,service_role;
commit;
